# Check GRPO QLoRA (original) and bf16 G=8 (plan_011)
for exp_id in ['mvp2_grpo_ced', 'mvp2_grpo_ced_kl001_r4', 'plan_011_grpo_g8_bf16']:
    exp = exps.get(exp_id, {})
    if not exp:
        continue
    spec = exp.get('spec', {}) or {}
    cmd = spec.get('command', '')
    reproduce = exp.get('reproduce', {}) or {}
    rcmd = reproduce.get('command', '')
    full_cmd = cmd or rcmd
    # Extract batch and GA
    batch = re.search(r'--per_device_batch_size\s+(\d+)', full_cmd)
    ga = re.search(r'--gradient_accumulation_steps\s+(\d+)', full_cmd)
    g = re.search(r'--num_generations\s+(\d+)', full_cmd)
    quant = '--no-quantize' not in full_cmd and '--quantize' in full_cmd or 'qlora' in full_cmd.lower() or '4bit' in full_cmd.lower()
